int is_prime(int n) {
    if (n < 2) return 0;
    for (int d = 2; d * d <= n; d++) {
        if (n % d == 0) return 0;
    }
    return 1;
}

int next_prime(int n) {
    int x = n + 1;
    while (!is_prime(x)) {
        x++;
    }
    return x;
}

