c-arrays-5.solution:
void rotate_left(int a[], int n) {
    if (n < 2) return;
    int first = a[0];
    for (int i = 0; i < n - 1; i++) {
        a[i] = a[i + 1];
    }
    a[n - 1] = first;
}

