c-strings-5.solution:
void capitalize(char s[]) {
    for (int i = 0; s[i] != '\0'; i++) {
        int start = (i == 0 || s[i - 1] == ' ');
        if (start && s[i] >= 'a' && s[i] <= 'z') {
            s[i] = s[i] - 'a' + 'A';
        } else if (!start && s[i] >= 'A' && s[i] <= 'Z') {
            s[i] = s[i] - 'A' + 'a';
        }
    }
}

