char lower(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A' + 'a';
    return c;
}

int is_palindrome_nocase(const char s[]) {
    int i = 0;
    int j = (int)strlen(s) - 1;
    while (i < j) {
        if (lower(s[i]) != lower(s[j])) return 0;
        i++;
        j--;
    }
    return 1;
}

