c-strings-6.solution:
#include <string.h>

int is_letter(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

char lower(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A' + 'a';
    return c;
}

int is_phrase_palindrome(const char s[]) {
    int i = 0;
    int j = (int)strlen(s) - 1;
    while (i < j) {
        if (!is_letter(s[i])) {
            i++;
        } else if (!is_letter(s[j])) {
            j--;
        } else {
            if (lower(s[i]) != lower(s[j])) return 0;
            i++;
            j--;
        }
    }
    return 1;
}

c-strings-6.harness:
int main(void) {
    CHECK_INT("\"A man, a plan, a canal: Panama\"", is_phrase_palindrome("A man, a plan, a canal: Panama"), 1);
    CHECK_INT("\"No lemon, no melon\"", is_phrase_palindrome("No lemon, no melon"), 1);
    CHECK_INT("\"gg wp\"", is_phrase_palindrome("gg wp"), 0);
    CHECK_INT("\"\"", is_phrase_palindrome(""), 1);
    CHECK_INT("\"!!\"", is_phrase_palindrome("!!"), 1);
    CHECK_INT("\"a.b\"", is_phrase_palindrome("a.b"), 0);
    return 0;
}

