void reverse_string(char *s) {
    if (*s == '\0') return;
    char *end = s;
    while (*(end + 1) != '\0') end++;
    while (s < end) {
        char tmp = *s;
        *s = *end;
        *end = tmp;
        s++;
        end--;
    }
}

