void tidy(char *s) {
    char *w = s;
    int pending = 0;
    for (const char *r = s; *r != '\0'; r++) {
        if (*r == ' ') {
            if (w != s) pending = 1;
        } else {
            if (pending) {
                *w = ' ';
                w++;
                pending = 0;
            }
            *w = *r;
            w++;
        }
    }
    *w = '\0';
}

