#define PI 3.14159265358979

enum ShapeKind { CIRCLE, RECTANGLE, TRIANGLE };

struct Shape {
    enum ShapeKind kind;
    union {
        struct { double radius; } circle;
        struct { double width, height; } rect;
        struct { double base, height; } tri;
    } as;
};

double area(const struct Shape *s) {
    switch (s->kind) {
    case CIRCLE:
        return PI * s->as.circle.radius * s->as.circle.radius;
    case RECTANGLE:
        return s->as.rect.width * s->as.rect.height;
    case TRIANGLE:
        return s->as.tri.base * s->as.tri.height / 2;
    }
    return 0;
}

double total_area(const struct Shape shapes[], int n) {
    double sum = 0;
    for (int i = 0; i < n; i++) sum += area(&shapes[i]);
    return sum;
}

int count_kind(const struct Shape shapes[], int n, enum ShapeKind k) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (shapes[i].kind == k) count++;
    }
    return count;
}

