char *join_words(char **words, int n, char sep) {
    size_t total = 1;
    for (int i = 0; i < n; i++) total += strlen(words[i]) + 1;
    char *out = malloc(total);
    if (out == NULL) return NULL;
    size_t pos = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0) out[pos++] = sep;
        size_t len = strlen(words[i]);
        memcpy(out + pos, words[i], len);
        pos += len;
    }
    out[pos] = '\0';
    return out;
}

