#include <stdio.h>

int join_names(char *buf, size_t size, const char **names, int n) {
    size_t used = 0;
    buf[0] = '\0';
    for (int i = 0; i < n; i++) {
        int w = snprintf(buf + used, size - used, "%s%s", i > 0 ? ", " : "", names[i]);
        if (w < 0 || (size_t)w >= size - used) return -1;
        used += (size_t)w;
    }
    return 0;
}

