#include <stdio.h>

int write_at(const char *path, int index, int value) {
    FILE *f = fopen(path, "r+b");
    if (f == NULL) return -1;
    if (fseek(f, 0, SEEK_END) != 0) {
        fclose(f);
        return 0;
    }
    long count = ftell(f) / (long)sizeof(int);
    if (index < 0 || index >= count) {
        fclose(f);
        return 0;
    }
    fseek(f, (long)index * (long)sizeof(int), SEEK_SET);
    int ok = fwrite(&value, sizeof value, 1, f) == 1;
    fclose(f);
    return ok ? 1 : 0;
}

