#include <limits.h>

int checked_mul(int a, int b, int *out) {
    if (a > 0) {
        if (b > 0) {
            if (a > INT_MAX / b) return 0;
        } else {
            if (b < INT_MIN / a) return 0;
        }
    } else if (a < 0) {
        if (b > 0) {
            if (a < INT_MIN / b) return 0;
        } else if (b < 0) {
            if (a < INT_MAX / b) return 0;
        }
    }
    *out = a * b;
    return 1;
}

