#include <stdarg.h>
#include <stdio.h>

int log_msg(char *buf, size_t size, const char *level, const char *fmt, ...) {
    int head = snprintf(buf, size, "[%s] ", level);
    if (head < 0) return head;
    size_t used = (size_t)head < size ? (size_t)head : size;
    va_list args;
    va_start(args, fmt);
    int body = vsnprintf(buf + used, size - used, fmt, args);
    va_end(args);
    if (body < 0) return body;
    return head + body;
}

