#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: head N FILE\n");
        return 2;
    }
    char *end;
    long n = strtol(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || n < 0) {
        fprintf(stderr, "head: bad count: %s\n", argv[1]);
        return 2;
    }
    FILE *f = fopen(argv[2], "r");
    if (f == NULL) {
        fprintf(stderr, "head: cannot open %s\n", argv[2]);
        return 1;
    }
    long lines = 0;
    int c;
    while (lines < n && (c = fgetc(f)) != EOF) {
        putchar(c);
        if (c == '\n') lines++;
    }
    fclose(f);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: find WORD FILE...\n");
        return 2;
    }
    const char *word = argv[1];
    int matched = 0, error = 0;
    char line[256];
    for (int i = 2; i < argc; i++) {
        FILE *f = fopen(argv[i], "r");
        if (f == NULL) {
            fprintf(stderr, "find: cannot open %s\n", argv[i]);
            error = 1;
            continue;
        }
        while (fgets(line, sizeof line, f) != NULL) {
            line[strcspn(line, "\n")] = '\0';
            if (strstr(line, word) != NULL) {
                printf("%s: %s\n", argv[i], line);
                matched = 1;
            }
        }
        fclose(f);
    }
    if (error) return 2;
    return matched ? 0 : 1;
}

