#include <string>

bool ends_with(const std::string& s, const std::string& suffix) {
    if (suffix.size() > s.size()) return false;
    std::size_t start = s.size() - suffix.size();
    for (std::size_t i = 0; i < suffix.size(); i++) {
        if (s[start + i] != suffix[i]) return false;
    }
    return true;
}

