int count_neighbors(const std::vector<std::string>& g, int r, int c) {
    int count = 0;
    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            if (dr == 0 && dc == 0) continue;
            int nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= (int)g.size()) continue;
            if (nc < 0 || nc >= (int)g[nr].size()) continue;
            if (g[nr][nc] == '#') count++;
        }
    }
    return count;
}

