    }
    void push(int v) {
        if (size_ == cap_) {
            int* bigger = new int[cap_ * 2];
            for (int i = 0; i < size_; i++) bigger[i] = data_[i];
            delete[] data_;
            data_ = bigger;
            cap_ *= 2;
        }
        data_[size_++] = v;
    }
    int pop() { return data_[--size_]; }
    int size() const { return size_; }
    const int* raw() const { return data_; }

private:
    int* data_;
    int size_;
    int cap_;
};

