int longest_unique_run(const std::string& s) {
    std::unordered_map<char, int> last;
    int best = 0, start = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        auto it = last.find(s[i]);
        if (it != last.end() && it->second >= start) start = it->second + 1;
        last[s[i]] = i;
        if (i - start + 1 > best) best = i - start + 1;
    }
    return best;
}

