    CHECK_EQ("10 - 3 (order matters)", eval_rpn(V{"10", "3", "-"}), 7);
    CHECK_EQ("20 / 4", eval_rpn(V{"20", "4", "/"}), 5);
    CHECK_EQ("negative number", eval_rpn(V{"-5", "2", "*"}), -10);
