bool copy_upper(const std::string& from, const std::string& to) {
    std::ifstream in(from);
    if (!in) return false;
    std::ofstream out(to);
    if (!out) return false;
    char c;
    while (in.get(c)) {
        if (c >= 'a' && c <= 'z') c = c - 'a' + 'A';
        out.put(c);
    }
    return static_cast<bool>(out);
}

