#include <string>

class UndoHistory {
public:
    explicit UndoHistory(int capacity) : capacity_(capacity) {}
    void push(const std::string& action) {
        actions_.push_back(action);
        if (static_cast<int>(actions_.size()) > capacity_) actions_.pop_front();
    }
    std::string undo() {
        if (actions_.empty()) return "";
        std::string last = actions_.back();
        actions_.pop_back();
        return last;
    }
    int size() const { return static_cast<int>(actions_.size()); }

private:
    int capacity_;
    std::deque<std::string> actions_;
};

