#include <deque>
#include <vector>

std::vector<int> window_max(const std::vector<int>& v, int k) {
    std::vector<int> out;
    std::deque<int> idx;
    for (int i = 0; i < static_cast<int>(v.size()); i++) {
        while (!idx.empty() && v[idx.back()] <= v[i]) idx.pop_back();
        idx.push_back(i);
        if (idx.front() <= i - k) idx.pop_front();
        if (i >= k - 1) out.push_back(v[idx.front()]);
    }
    return out;
}

