#include <queue>
#include <string>
#include <utility>
#include <vector>

std::vector<std::string> run_order(const std::vector<std::pair<int, std::string>>& tasks) {
    using Task = std::pair<int, std::string>;
    auto runs_later = [](const Task& a, const Task& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second > b.second;
    };
    std::priority_queue<Task, std::vector<Task>, decltype(runs_later)> queue(runs_later);
    for (const auto& t : tasks) queue.push(t);
    std::vector<std::string> out;
    while (!queue.empty()) {
        out.push_back(queue.top().second);
        queue.pop();
    }
    return out;
}

