class Commands {
public:
    void add(const std::string& name, std::function<std::string(const std::vector<std::string>&)> fn) {
        commands_[name] = fn;
    }
    std::string run(const std::string& line) const {
        std::istringstream in(line);
        std::string name;
        if (!(in >> name)) return "";
        std::vector<std::string> args;
        std::string word;
        while (in >> word) args.push_back(word);
        auto it = commands_.find(name);
        if (it == commands_.end()) return "unknown command: " + name;
        return it->second(args);
    }

private:
