};

std::unique_ptr<Node> build(const std::vector<int>& v) {
    std::unique_ptr<Node> head;
    for (auto it = v.rbegin(); it != v.rend(); ++it) {
        head = std::make_unique<Node>(Node{*it, std::move(head)});
    }
