#include <memory>
#include <string>

class TextureCache {
public:
    std::shared_ptr<std::string> get(const std::string& name) {
        auto it = cache_.find(name);
        if (it != cache_.end()) return it->second;
        loads_++;
        auto tex = std::make_shared<std::string>("texture:" + name);
        cache_[name] = tex;
        return tex;
    }
    int loads() const { return loads_; }

private:
    int loads_ = 0;
    std::map<std::string, std::shared_ptr<std::string>> cache_;
};

