std::vector<std::string> drain_long(std::vector<std::string>& src, std::size_t min_len) {
    std::vector<std::string> out, keep;
    for (auto& s : src) {
        if (s.size() >= min_len) out.push_back(std::move(s));
        else keep.push_back(std::move(s));
