#include <string>
#include <utility>
#include <vector>

class Batcher {
public:
    explicit Batcher(int n) : n_(n) {}
    void add(std::string line) {
        current_.push_back(std::move(line));
        if (static_cast<int>(current_.size()) == n_) done_.push_back(std::exchange(current_, {}));
    }
    int pending() const { return static_cast<int>(current_.size()); }
    std::vector<std::vector<std::string>> take_batches() { return std::exchange(done_, {}); }

private:
    int n_;
    std::vector<std::string> current_;
    std::vector<std::vector<std::string>> done_;
};

