constexpr bool is_prime(int n) {
    if (n < 2) return false;
    for (int d = 2; d * d <= n; d++) {
        if (n % d == 0) return false;
    }
    return true;
}

constexpr int count_primes_below(int n) {
    int count = 0;
    for (int i = 2; i < n; i++) {
        if (is_prime(i)) count++;
    }
    return count;
}

