#include <algorithm>
#include <functional>
#include <queue>
#include <vector>

template <typename T>
class TopK {
public:
    explicit TopK(int k) : k_(k) {}
    void add(const T& v) {
        heap_.push(v);
        if ((int)heap_.size() > k_) heap_.pop();
    }
    std::vector<T> items() const {
        auto copy = heap_;
        std::vector<T> out;
        while (!copy.empty()) {
            out.push_back(copy.top());
            copy.pop();
        }
        std::reverse(out.begin(), out.end());
        return out;
    }

private:
    int k_;
    std::priority_queue<T, std::vector<T>, std::greater<T>> heap_;
};

