class Backpack {
public:
    explicit Backpack(int limit) : limit_(limit) {}
    bool add(const std::string& item, int qty) {
        if (qty <= 0 || total_ + qty > limit_) return false;
        items_[item] += qty;
        total_ += qty;
        return true;
    }
    bool remove(const std::string& item, int qty) {
        auto it = items_.find(item);
        if (qty <= 0 || it == items_.end() || it->second < qty) return false;
        it->second -= qty;
        total_ -= qty;
        if (it->second == 0) items_.erase(it);
        return true;
    }
    int total() const { return total_; }
    int count(const std::string& item) const {
        auto it = items_.find(item);
        return it == items_.end() ? 0 : it->second;
    }

private:
    int limit_;
    std::map<std::string, int> items_;
    int total_ = 0;
};

