class Cooldown {
public:
    Cooldown(const Clock& clock, long seconds) : clock_(clock), seconds_(seconds) {}
    bool ready() const { return !used_ || clock_.now() >= last_ + seconds_; }
    bool use() {
        if (!ready()) return false;
        used_ = true;
        last_ = clock_.now();
        return true;
    }

private:
