struct Idle {};
struct Planting { int progress; };
struct Planted { int timer; };
using State = std::variant<Idle, Planting, Planted>;

State step(const State& s, const std::string& input) {
    if (std::holds_alternative<Idle>(s)) {
        if (input == "plant") return Planting{1};
        return s;
    }
    if (const auto* p = std::get_if<Planting>(&s)) {
        if (input != "plant") return Idle{};
        if (p->progress + 1 >= 3) return Planted{40};
        return Planting{p->progress + 1};
    }
    const auto& planted = std::get<Planted>(s);
    if (input == "tick") return Planted{planted.timer - 1};
    return s;
}

