#include <string_view>

std::string_view longest_word(std::string_view text) {
    std::string_view best;
    std::size_t i = 0;
    while (i < text.size()) {
        while (i < text.size() && text[i] == ' ') i++;
        std::size_t start = i;
        while (i < text.size() && text[i] != ' ') i++;
        if (i - start > best.size()) best = text.substr(start, i - start);
    }
    return best;
}

