#include <vector>

std::vector<int> even_squares(const std::vector<int>& v, int n) {
    std::vector<int> out;
    for (int x : v | std::views::filter([](int x) { return x % 2 == 0; })
                   | std::views::transform([](int x) { return x * x; })
                   | std::views::take(n)) {
        out.push_back(x);
    }
    return out;
}

