#include <algorithm>
#include <span>

int count_pattern(std::span<const int> xs, std::span<const int> pat) {
    if (pat.empty() || pat.size() > xs.size()) return 0;
    int n = 0;
    for (std::size_t i = 0; i + pat.size() <= xs.size(); i++) {
        if (std::ranges::equal(xs.subspan(i, pat.size()), pat)) n++;
    }
    return n;
}

