struct ArgsResult {
    std::map<std::string, std::string> values;
    std::string error;   // empty means success
};

ArgsResult parse_args(const std::vector<std::string>& args) {
    ArgsResult r;
    for (std::size_t i = 0; i < args.size(); i++) {
        std::string where = "argument " + std::to_string(i + 1) + ": ";
        const std::string& a = args[i];
        if (a.rfind("--", 0) != 0) return {{}, where + "expected --"};
        std::string body = a.substr(2);
        auto eq = body.find('=');
        std::string name = body.substr(0, eq);
        std::string value = eq == std::string::npos ? "true" : body.substr(eq + 1);
        if (name.empty()) return {{}, where + "empty name"};
        if (!r.values.emplace(name, value).second) return {{}, where + "duplicate " + name};
    }
    return r;
}

