cpp-errors-6.solution:
#include <map>
#include <string>

struct Settings {
    int port = 0;
    std::string host;
    bool debug = false;
};

struct SettingsResult {
    Settings settings;
    std::string error;   // empty means success
};

SettingsResult to_settings(const std::map<std::string, std::string>& v) {
    auto fail = [](const std::string& e) { return SettingsResult{{}, e}; };
    Settings s;
    auto p = v.find("port");
    if (p == v.end()) return fail("missing port");
    const std::string& text = p->second;
    if (text.empty()) return fail("port is not a number");
    for (char c : text)
        if (c < '0' || c > '9') return fail("port is not a number");
    std::size_t first = text.find_first_not_of('0');
    if (first != std::string::npos && text.size() - first > 5) return fail("port out of range");
    int port = std::stoi(text);
    if (port < 1 || port > 65535) return fail("port out of range");
    s.port = port;
    auto h = v.find("host");
    s.host = h == v.end() ? "localhost" : h->second;
    auto d = v.find("debug");
    if (d != v.end()) {
        if (d->second == "true") s.debug = true;
        else if (d->second == "false") s.debug = false;
        else return fail("debug must be true or false");
    }
    return {s, ""};
}

