#include <map>
int main() {
    auto a = to_settings({{"port", "8080"}});
    CHECK_EQ("ok", a.error, std::string(""));
    CHECK_EQ("port", a.settings.port, 8080);
    CHECK_EQ("default host", a.settings.host, std::string("localhost"));
    CHECK("default debug", !a.settings.debug);
    auto b = to_settings({{"port", "27015"}, {"host", "arena.gg"}, {"debug", "true"}});
    CHECK("all set", b.settings.port == 27015 && b.settings.host == "arena.gg" && b.settings.debug);
    CHECK_EQ("missing port", to_settings({{"host", "x"}}).error, std::string("missing port"));
    CHECK_EQ("letters", to_settings({{"port", "80a"}}).error, std::string("port is not a number"));
    CHECK_EQ("empty port", to_settings({{"port", ""}}).error, std::string("port is not a number"));
    CHECK_EQ("zero", to_settings({{"port", "0"}}).error, std::string("port out of range"));
    CHECK_EQ("too big", to_settings({{"port", "70000"}}).error, std::string("port out of range"));
    CHECK_EQ("huge", to_settings({{"port", "123456789012"}}).error, std::string("port out of range"));
    CHECK_EQ("leading zeros", to_settings({{"port", "0000080"}}).settings.port, 80);
    CHECK_EQ("bad debug", to_settings({{"port", "80"}, {"debug", "yes"}}).error, std::string("debug must be true or false"));
}
